insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) select id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id from jsonb_to_recordset($bank$[{"id":"che-so-164","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Pure toluene has vapour pressure 30 torr. In an ideal mix with $x_{\\mathrm{toluene}} = 0.40$, the partial pressure of toluene is","options":["12 torr","30 torr","18 torr","70 torr"],"answer_index":0,"explanation":"$p = p^\\circ x = 30 \\times 0.40 = 12$ torr.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"raoult-vapour"},{"id":"che-so-165","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"An ideal pair has $p_A^\\circ = 80$ mm Hg and $p_B^\\circ = 20$ mm Hg. At $x_A = 0.50$ the total pressure is","options":["50 mm Hg","100 mm Hg","80 mm Hg","20 mm Hg"],"answer_index":0,"explanation":"$p = 80 \\times 0.50 + 20 \\times 0.50 = 50$ mm Hg.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"raoult-vapour"},{"id":"che-so-166","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Benzene ($p^\\circ = 75$ torr) plus a non-volatile solute form a liquid with $x_{\\mathrm{benzene}} = 0.90$. The vapour pressure of that solution is","options":["67.5 torr","75 torr","7.5 torr","83 torr"],"answer_index":0,"explanation":"Only benzene contributes: $p = 75 \\times 0.90 = 67.5$ torr.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"raoult-vapour"},{"id":"che-so-167","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Above an ideal liquid the partial pressure of A is 24 kPa while the total pressure is 60 kPa. The vapour mole fraction of A is","options":["0.40","0.24","0.60","1.0"],"answer_index":0,"explanation":"$y_A = p_A / p_{\\mathrm{total}} = 24/60 = 0.40$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"raoult-vapour"},{"id":"che-so-168","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Component B is non-volatile. If $x_{\\mathrm{solvent}} = 0.95$ and $p^\\circ_{\\mathrm{solvent}} = 20$ kPa, the solution vapour pressure equals","options":["19 kPa","20 kPa","1 kPa","21 kPa"],"answer_index":0,"explanation":"$p = 20 \\times 0.95 = 19$ kPa.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"raoult-vapour"},{"id":"che-so-169","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Two ideal liquids are present in equal mole fractions. $p_A^\\circ = 90$ torr and $p_B^\\circ = 60$ torr. Total vapour pressure is","options":["75 torr","150 torr","90 torr","30 torr"],"answer_index":0,"explanation":"$p = 0.50 \\times 90 + 0.50 \\times 60 = 75$ torr.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"raoult-vapour"},{"id":"che-so-170","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Vapour over an ideal mix is analysed as $y_A = 0.70$ when $p_{\\mathrm{total}} = 100$ torr. Partial pressure of A in that vapour is","options":["70 torr","30 torr","100 torr","0.70 torr"],"answer_index":0,"explanation":"$p_A = y_A p_{\\mathrm{total}} = 0.70 \\times 100 = 70$ torr.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"raoult-vapour"},{"id":"che-so-171","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"An ideal blend has $x_A = 0.30$, $p_A^\\circ = 200$ torr and $p_B^\\circ = 100$ torr. Mole fraction of A in the vapour is nearest","options":["0.46","0.30","0.67","0.23"],"answer_index":0,"explanation":"$p_A = 60$ torr, $p_B = 70$ torr, $p = 130$ torr, so $y_A = 60/130 \\approx 0.46$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"raoult-vapour"},{"id":"che-so-172","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"At 350 K the liquid mole fraction of hexane is 0.25 ($p^\\circ_{\\mathrm{hex}} = 90$ kPa, $p^\\circ_{\\mathrm{hept}} = 30$ kPa). Total vapour pressure of this ideal pair is","options":["45 kPa","60 kPa","30 kPa","120 kPa"],"answer_index":0,"explanation":"$p = 90 \\times 0.25 + 30 \\times 0.75 = 22.5 + 22.5 = 45$ kPa.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"raoult-vapour"},{"id":"che-so-173","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"An ideal liquid solution is characterised by","options":["$\\Delta H_{\\mathrm{mix}} = 0$ and $\\Delta V_{\\mathrm{mix}} = 0$","$\\Delta H_{\\mathrm{mix}} > 0$ only","$\\Delta G_{\\mathrm{mix}} = 0$","$\\Delta S_{\\mathrm{mix}} = 0$"],"answer_index":0,"explanation":"No heat is absorbed or evolved and the volumes are strictly additive for an ideal mix.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"ideal-nonideal"},{"id":"che-so-174","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Molecular interactions in an ideal A–B solution satisfy","options":["A–A, B–B and A–B forces of similar strength","A–B much stronger than like pairs","A–B much weaker than like pairs","no A–B contacts at all"],"answer_index":0,"explanation":"Equal interaction energies make the mixture obey Raoult’s law at all compositions.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"ideal-nonideal"},{"id":"che-so-175","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Benzene and toluene form a nearly ideal pair because they have","options":["similar size and intermolecular forces","opposite polarity","hydrogen bonds of very different strength","ionic lattices"],"answer_index":0,"explanation":"Both are non-polar aromatics of comparable size, so A–B forces match A–A and B–B.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"ideal-nonideal"},{"id":"che-so-176","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A non-ideal solution is one that","options":["deviates from Raoult’s law","obeys Raoult’s law at every mole fraction","has $\\Delta H_{\\mathrm{mix}}$ exactly zero","never boils"],"answer_index":0,"explanation":"Any measurable departure of vapour pressure from $p_i^\\circ x_i$ marks non-ideality.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"ideal-nonideal"},{"id":"che-so-177","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Positive deviation from Raoult’s law means the observed vapour pressure is","options":["higher than the ideal value","lower than the ideal value","exactly zero","equal to $K_H$"],"answer_index":0,"explanation":"Weaker A–B forces let molecules escape more easily, so $p > p_{\\mathrm{ideal}}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"ideal-nonideal"},{"id":"che-so-178","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Negative deviation from Raoult’s law is accompanied by","options":["$\\Delta H_{\\mathrm{mix}} < 0$","$\\Delta H_{\\mathrm{mix}} > 0$","$\\Delta H_{\\mathrm{mix}} = 0$","$\\Delta V_{\\mathrm{mix}} > 0$ in every case"],"answer_index":0,"explanation":"Stronger A–B attractions release heat on mixing (exothermic).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"ideal-nonideal"},{"id":"che-so-179","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"For a positively deviating pair, mixing typically causes the volume to","options":["increase ($\\Delta V_{\\mathrm{mix}} > 0$)","decrease","stay exactly additive","collapse to zero"],"answer_index":0,"explanation":"Weaker unlike attractions leave a slightly expanded, less tightly packed liquid.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"ideal-nonideal"},{"id":"che-so-180","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Chloroform and acetone show negative deviation because","options":["a hydrogen-bond-like attraction forms between the two molecules","the liquids repel strongly","they are immiscible","they ionise completely"],"answer_index":0,"explanation":"The chloroform hydrogen interacts with the acetone oxygen, strengthening A–B forces.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"ideal-nonideal"},{"id":"che-so-181","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Ethanol–acetone is a common Intermediate example of","options":["positive deviation","negative deviation","an ideal mix","a solid solution"],"answer_index":0,"explanation":"Mixing breaks some ethanol hydrogen bonds, so A–B is weaker than A–A and the pair shows positive deviation.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"ideal-nonideal"},{"id":"che-so-182","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"n-Hexane and n-heptane are expected to behave as","options":["an ideal solution","a strongly positive pair","a strongly negative pair","an azeotrope only"],"answer_index":0,"explanation":"Adjacent homologues have nearly identical London forces, so the mix is essentially ideal.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"ideal-nonideal"},{"id":"che-so-183","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"When A–B attractions are weaker than A–A and B–B, the mixture shows","options":["positive deviation and often a minimum-boiling azeotrope","negative deviation and a maximum-boiling azeotrope","strictly ideal behaviour","zero vapour pressure"],"answer_index":0,"explanation":"Weaker unlike forces raise vapour pressure; a maximum in p versus x gives a minimum-boiling azeotrope.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"ideal-nonideal"}]$bank$::jsonb) as t(id text, chapter_id text, subject_id text, stem text, options jsonb, answer_index int, explanation text, images jsonb, source jsonb, difficulty text, concept_id text) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
insert into question_pyq_meta (question_id, appear_count, years, exams, verified) select question_id, appear_count, years, exams, verified from jsonb_to_recordset($meta$[{"question_id":"che-so-164","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-165","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-166","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-167","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-168","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-169","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-170","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-171","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-172","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-173","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-174","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-175","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-176","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-177","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-178","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-179","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-180","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-181","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-182","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-183","appear_count":0,"years":[],"exams":[],"verified":false}]$meta$::jsonb) as t(question_id text, appear_count int, years int[], exams text[], verified boolean) on conflict (question_id) do update set appear_count = excluded.appear_count, years = excluded.years, exams = excluded.exams, verified = excluded.verified;
